 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    private int res;
    public int findSecondMinimumValue(TreeNode root) {
        res = -1;
        traverse(root, root.val);
        return res;
    }

    private void traverse(TreeNode root, int min) {
        if (root == null) {
            return;
        }
        traverse(root.left, min);
        traverse(root.right, min);
        if (root.val > min) {
            res = res == -1 ? root.val : Math.min(res, root.val);
        }
    }
}

package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

public class SecondMinimumNodeInABinaryTree {

    int min;
    int secondMin = Integer.MAX_VALUE;
    boolean flag = false;

    public int findSecondMinimumValue(TreeNode root) {
        min = root.val;
        findSecondMinimumValueUtil(root);
        if (flag) {
            return secondMin;
        }
        return -1;

    }

    public void findSecondMinimumValueUtil(TreeNode root) {
        if (root == null) return;

        if (root.val == min) {
            findSecondMinimumValueUtil(root.left);
            findSecondMinimumValueUtil(root.right);
        } else {
            secondMin = Math.min(secondMin, root.val);
            flag = true;
        }
    }

}

class Solution {
    public void dfs(TreeNode root, Set<Integer> uniques) {
        if (root != null) {
            uniques.add(root.val);
            dfs(root.left, uniques);
            dfs(root.right, uniques);
        }
    }
    public int findSecondMinimumValue(TreeNode root) {
        Set<Integer> uniques = new HashSet<Integer>();
        dfs(root, uniques);

        int min1 = root.val;
        long ans = Long.MAX_VALUE;
        for (int v : uniques) {
            if (min1 < v && v < ans) ans = v;
        }
        return ans < Long.MAX_VALUE ? (int) ans : -1;
    }
}

class Solution {
    int min1;
    long ans = Long.MAX_VALUE;

    public void dfs(TreeNode root) {
        if (root != null) {
            if (min1 < root.val && root.val < ans) {
                ans = root.val;
            } else if (min1 == root.val) {
                dfs(root.left);
                dfs(root.right);
            }
        }
    }
    public int findSecondMinimumValue(TreeNode root) {
        min1 = root.val;
        dfs(root);
        return ans < Long.MAX_VALUE ? (int) ans : -1;
    }
}

